10	// Ticket-building stays server-side (uses Buffer, reads kitchen_printers via
11	// the caller's Supabase client) — only the actual byte-sending moves to the
12	// browser via the print agent, since Vercel can never reach a printer's
13	// private LAN IP but the cashier's browser (physically on the shop's
14	// network) can. See print-agent/ and src/lib/print-agent-client.ts.
15	export type KitchenPrintJobPayload = { printerName: string; address: string; bytesBase64: string };
16	
17	export async function buildKitchenPrintJobs(
18	  supabase: SupabaseClient,
19	  businessId: string,
20	  job: KitchenPrintJob,
21	): Promise<KitchenPrintJobPayload[]> {
22	  if (job.items.length === 0) return [];
23	
24	  const { data: printers } = await supabase
25	    .from("kitchen_printers")
26	    .select("id, name, categories, connection_type, address")
27	    .eq("business_id", businessId);
28	
29	  const lanPrinters = (printers ?? []).filter(
30	    (p) => p.connection_type === "lan" && !!p.address,
31	  ) as { id: string; name: string; categories: string[]; connection_type: "lan"; address: string }[];
32	
33	  const attempts = lanPrinters
34	    .map((printer) => {
35	      const items =
36	        printer.categories.length > 0
37	          ? job.items.filter((i) => i.category && printer.categories.includes(i.category))
38	          : job.items;
39	      return { printer, items };
40	    })
41	    .filter((a) => a.items.length > 0);
42	
43	  return attempts.map(({ printer, items }) => {
44	    const buffer = buildKitchenTicket({
45	      station: printer.name,
46	      source: job.source,
47	      label: job.label,
48	      items,
49	    });
50	    return {
51	      printerName: printer.name,
52	      address: printer.address,
53	      bytesBase64: buffer.toString("base64"),
54	    };
55	  });
56	}
