7	// Fire-and-forget from the caller's point of view — a failed kitchen print
8	// must never block or fail the sale/order that triggered it (same principle
9	// the old server-side dispatchKitchenPrint followed).
10	export async function dispatchPrintJobs(businessId: string, jobs: KitchenPrintJobPayload[]) {
11	  if (jobs.length === 0) return;
12	
13	  const results = await Promise.all(
14	    jobs.map(async (job) => ({ job, result: await printViaAgent(job.address, job.bytesBase64) })),
15	  );
16	
17	  const failed = results.filter((r) => !r.result.ok);
18	  if (failed.length > 0) {
19	    await logKitchenPrintFailures(
20	      businessId,
21	      failed.map(({ job, result }) => ({
22	        printer: job.printerName,
23	        error: result.ok ? "" : result.error,
24	      })),
25	    ).catch(() => {});
26	  }
27	}
